def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    colors = set(counts) - {bg}
    for color in colors:
        # Join facing endpoints of collinear runs. A point passing through
        # in the perpendicular axis is not a free endpoint for this join.
        def cross_through(r, c, axis):
            if axis == 'h':
                left = any(grid[r][x] == color for x in range(c))
                right = any(grid[r][x] == color for x in range(c+1, w))
            else:
                left = any(grid[x][c] == color for x in range(r))
                right = any(grid[x][c] == color for x in range(r+1, h))
            return left and right
        for r in range(h):
            pos = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(pos, pos[1:]):
                if b > a+1 and not cross_through(r,a,'v') and not cross_through(r,b,'v'):
                    for c in range(a+1,b):
                        if grid[r][c] == bg: out[r][c] = 2
        for c in range(w):
            pos = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(pos, pos[1:]):
                if b > a+1 and not cross_through(a,c,'h') and not cross_through(b,c,'h'):
                    for r in range(a+1,b):
                        if grid[r][c] == bg: out[r][c] = 2
    return out
